    #[test]
    #[allow(clippy::too_many_lines)] // Recovery and raw-write invalidation use the same real alias producer.
    fn property_alias_function_recovery_is_exact_and_separate_from_normal_mapping() {
        for mutation in ["source", "proxy", "parameter"] {
            let parsed = property_function_source();
            let file = FileId::new(19_923);
            let mut fixture = property_function_fixture(&parsed, file);
            let error = fixture
                .context
                .store()
                .intrinsic_bootstrap()
                .unwrap()
                .error_type;
            let mut session = InstantiationSession::new_recovering(
                fixture.context.store(),
                InstantiationLimits {
                    max_count: 0,
                    ..InstantiationLimits::default()
                },
                error,
            )
            .unwrap();
            let value =
                demand_property_function(&mut fixture, &parsed, file, &mut session).unwrap();
            assert_eq!(session.limit_event_count(), 1);
            assert_eq!((session.query_count(), session.total_count()), (0, 0));
            let store = fixture.context.store();
            let signature = property_function_callable(store, value, error);
            let parameter = store.signature(signature).unwrap().parameters()[0];
            let recovery = store
                .instantiated_property_recovery(fixture.property)
                .unwrap();
            assert!(!recovery.method);
            assert!(recovery.checked_identity(store).is_some());
            let Some(StoredCallableSetValidation::Valid { edges, .. }) =
                validate_instantiated_function_member_callable(store, value)
            else {
                unreachable!()
            };
            assert!(edges.contains(&fixture.source));
            assert!(edges.contains(&store.intrinsic_bootstrap().unwrap().string_type));
            let alias = property_object_alias_projection(store, fixture.receiver)
                .unwrap()
                .unwrap();
            assert!(
                alias
                    .arguments
                    .iter()
                    .chain(&alias.identity_arguments)
                    .all(|argument| edges.contains(argument))
            );
            assert!(!edges.contains(&fixture.receiver));
            store
                .validate_cached_array_capability_with_array_targets(
                    CanonicalArrayTargets::from_global_types(fixture.context.global_types()),
                    value,
                )
                .unwrap();
            assert!(
                !instantiated_member_type_matches(
                    store,
                    fixture.source,
                    value,
                    fixture.mapper,
                    None
                )
                .unwrap()
            );
            let before = property_recovery_store_counts(store);
            assert_eq!(
                demand_property_function(&mut fixture, &parsed, file, &mut session),
                Ok(value)
            );
            assert_eq!(
                property_recovery_store_counts(fixture.context.store()),
                before
            );
            assert_eq!(session.limit_event_count(), 1);
            let store = fixture.context.store_mut_for_test();
            let symbol = match mutation {
                "source" => fixture.source_property,
                "proxy" => fixture.property,
                "parameter" => parameter,
                _ => unreachable!(),
            };
            let links = store.value_symbol_links(symbol).cloned().unwrap();
            let number = store.intrinsic_bootstrap().unwrap().number_type;
            assert!(store.set_value_symbol_links(
                symbol,
                ValueSymbolLinks {
                    resolved_type: Some(number),
                    ..links.clone()
                }
            ));
            let before = property_recovery_store_counts(store);
            assert!(
                matches!(
                    validate_instantiated_function_member_callable(store, value),
                    Some(StoredCallableSetValidation::Malformed { .. })
                ),
                "{mutation}"
            );
            assert!(
                demand_property_function(&mut fixture, &parsed, file, &mut session).is_err(),
                "{mutation}"
            );
            assert_eq!(
                property_recovery_store_counts(fixture.context.store()),
                before
            );
            assert_eq!(session.limit_event_count(), 1);
            assert!(
                fixture
                    .context
                    .store_mut_for_test()
                    .set_value_symbol_links(symbol, links)
            );
            assert!(
                matches!(
                    validate_instantiated_function_member_callable(fixture.context.store(), value),
                    Some(StoredCallableSetValidation::Malformed { .. })
                ),
                "a raw restore cannot recreate a producer recovery: {mutation}"
            );
            assert_eq!(
                property_recovery_store_counts(fixture.context.store()),
                before
            );
        }
    }

    fn array_property_function_source(annotation: &str, argument: &str) -> ParseResult {
        parse_source_file(&format!(
            "interface Array<T> {{}} interface ReadonlyArray<T> {{}} \
             type Observer<T> = {{ next: (value: {annotation}) => {annotation}; }}; \
             declare const observer: Observer<{argument}>;",
        ))
    }

    fn array_property_function_options() -> CanonicalCheckerOptions {
        CanonicalCheckerOptions {
            intrinsic: IntrinsicBootstrapOptions {
                strict_null_checks: true,
                ..IntrinsicBootstrapOptions::default()
            },
            ..CanonicalCheckerOptions::default()
        }
    }

    #[test]
    #[allow(clippy::too_many_lines)] // The copied return has an actual array edge under both read capabilities.
    fn inline_property_function_signature_returns_require_both_array_capabilities() {
        use crate::semantic::{DeclaredTypeError, TypeNodeUnavailable};

        for (annotation, argument) in [("T[]", "string"), ("T", "string[]")] {
            let parsed = array_property_function_source(annotation, argument);
            let file = FileId::new(20_210);
            let mut fixture = property_function_fixture_with_options(
                &parsed,
                file,
                array_property_function_options(),
                false,
            );
            let targets = CanonicalArrayTargets::from_global_types(fixture.context.global_types());
            let mut session = InstantiationSession::new(InstantiationLimits::default());
            let value =
                demand_property_function(&mut fixture, &parsed, file, &mut session).unwrap();
            let store = fixture.context.store();
            let original = store.instantiated_property_alias_callable(value).unwrap();
            let signature = original.signature;
            let expected = store
                .signature(signature)
                .unwrap()
                .resolved_return_type()
                .unwrap();
            let array = store
                .canonical_array_reference(fixture.context.global_types(), expected)
                .unwrap()
                .unwrap();
            assert_eq!(
                array.element_type,
                store.intrinsic_bootstrap().unwrap().string_type
            );
            let mut foreign = CanonicalTypeMapperStore::new();
            let foreign_type = foreign
                .alloc_intrinsic_type(TypeFlags::ANY, "foreign")
                .unwrap();
            let foreign_targets = CanonicalArrayTargets::for_test(foreign_type, foreign_type);
            let wrong_targets =
                CanonicalArrayTargets::for_single_target_validation(targets.readonly_array_type());
            let snapshot = |store: &CanonicalTypeMapperStore| {
                (
                    property_recovery_store_counts(store),
                    store.instantiated_property_alias_callable_len(),
                    store.instantiated_property_alias_callable_signature_len(),
                )
            };
            let before = snapshot(store);
            let work = (
                session.query_count(),
                session.total_count(),
                session.limit_event_count(),
            );
            for current in [None, Some(wrong_targets), Some(foreign_targets)] {
                for _ in 0..2 {
                    assert_eq!(
                        instantiated_property_function_signature_return_type(
                            fixture.context.store(),
                            signature,
                            current,
                        ),
                        Err(RelationUnavailable::InvalidStructuredMembers(value))
                    );
                    assert_eq!(snapshot(fixture.context.store()), before);
                }
            }
            assert_eq!(
                query_property_function_return(
                    &mut fixture,
                    &parsed,
                    file,
                    signature,
                    &mut session,
                    false,
                ),
                Err(DeclaredTypeError::TypeNodeUnavailable(
                    TypeNodeUnavailable::InvalidFunctionSignature(signature)
                ))
            );
            for recorded in [None, Some(wrong_targets), Some(foreign_targets)] {
                let damaged = InstantiatedPropertyAliasCallable {
                    array_targets: recorded,
                    ..original
                };
                assert_eq!(
                    fixture
                        .context
                        .store_mut_for_test()
                        .replace_instantiated_property_alias_callable_for_test(
                            value,
                            Some(damaged)
                        ),
                    Some(original)
                );
                for _ in 0..2 {
                    assert_eq!(
                        query_property_function_return(
                            &mut fixture,
                            &parsed,
                            file,
                            signature,
                            &mut session,
                            true,
                        ),
                        Err(DeclaredTypeError::TypeNodeUnavailable(
                            TypeNodeUnavailable::InvalidFunctionSignature(signature)
                        ))
                    );
                    assert_eq!(snapshot(fixture.context.store()), before);
                    assert_eq!(
                        (
                            session.query_count(),
                            session.total_count(),
                            session.limit_event_count()
                        ),
                        work
                    );
                }
                assert_eq!(
                    fixture
                        .context
                        .store_mut_for_test()
                        .replace_instantiated_property_alias_callable_for_test(
                            value,
                            Some(original)
                        ),
                    Some(damaged)
                );
                assert_eq!(
                    query_property_function_return(
                        &mut fixture,
                        &parsed,
                        file,
                        signature,
                        &mut session,
                        true,
                    ),
                    Ok(expected)
                );
                assert_eq!(snapshot(fixture.context.store()), before);
            }
            assert_eq!(
                (
                    session.query_count(),
                    session.total_count(),
                    session.limit_event_count()
                ),
                work
            );
            assert!(fixture.diagnostics.is_empty());
        }
    }

    #[test]
    fn property_alias_function_outer_parameter_union_is_an_atomic_source_boundary() {
        use crate::semantic::{DeclaredTypeError, TypeNodeUnavailable};

        let parsed = array_property_function_source("T | undefined", "string[]");
        let file = FileId::new(19_924);
        let options = array_property_function_options();
        let mut context = checker_context(&parsed, file, options);
        let receiver = property_object_alias_variable_type(&parsed, file, &mut context, "observer");
        let original = property_object_alias_projection(context.store(), receiver)
            .unwrap()
            .unwrap();
        let property = &original.properties[0];
        let NodeData::FunctionTypeNode(function) =
            &parsed.arena.get(property.type_node.node).unwrap().data
        else {
            panic!("next retains its function type annotation");
        };
        let NodeData::ParameterDeclaration(parameter) =
            &parsed.arena.get(function.parameters.nodes[0]).unwrap().data
        else {
            panic!("next retains its value parameter");
        };
        let NodeData::UnionTypeNode(union) =
            &parsed.arena.get(parameter.type_.unwrap()).unwrap().data
        else {
            panic!("value retains its written union annotation");
        };
        let unsupported = NodeRef::new(parsed.arena.id(), file, union.types.nodes[0]);
        let globals = context.global_types().clone();
        let bound = context.file(file).unwrap().1.clone();
        let host = DeclaredTypeHost::new_after_global_merge(
            [(&parsed.arena, &bound)],
            crate::semantic::production::GlobalMergeCompletion::for_test(options.name_resolution),
        )
        .unwrap();
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let mut session = InstantiationSession::new(InstantiationLimits::default());
        let store = context.store_mut_for_test();
        resolve_property_object_alias_members(store, original.target).unwrap();
        let before = (
            property_recovery_store_counts(store),
            store.instantiated_property_alias_callable_len(),
            store.value_symbol_links(property.symbol).cloned(),
            store.type_node_links(property.type_node).cloned(),
            store.signature_links(property.type_node).cloned(),
        );
        for _ in 0..2 {
            assert_eq!(
                demand_property_object_alias_property(
                    store,
                    &host,
                    &globals,
                    options,
                    &mut session,
                    &mut diagnostics,
                    original.target,
                    property.symbol,
                ),
                Err(SourceCheckError::DeclaredType(
                    DeclaredTypeError::TypeNodeUnavailable(
                        TypeNodeUnavailable::UnsupportedUnionConstituent(unsupported)
                    )
                ))
            );
            assert_eq!(
                (
                    property_recovery_store_counts(store),
                    store.instantiated_property_alias_callable_len(),
                    store.value_symbol_links(property.symbol).cloned(),
                    store.type_node_links(property.type_node).cloned(),
                    store.signature_links(property.type_node).cloned(),
                ),
                before
            );
            assert_eq!(
                (
                    session.query_count(),
                    session.total_count(),
                    session.limit_event_count()
                ),
                (0, 0, 0)
            );
            assert!(diagnostics.is_empty());
        }
    }

